  bash rex21.sh --swap-status           查看Swap/ZRAM容量、使用量和文件大小
  bash rex21.sh --swap-prepare          磁盘Swap总量目标530MiB，只补差额；无ZRAM时尝试添加
  bash rex21.sh --uninstall-preview     预览完整卸载范围
  bash rex21.sh --uninstall             完整卸载REX（输入UNINSTALL确认删除节点/密钥）
  bash rex21.sh --uninstall-yes         明确确认完整卸载，无交互提示
  bash rex21.sh --policy-status         查看握手、版本范围、回放与出站策略
  bash rex21.sh --stats                 查看本机连接及 Vision DIRECT/splice 汇总（核心0.5.0及以上）
  bash rex21.sh --client                显示节点信息、VLESS 链接和终端二维码
  bash rex21.sh --status                查看服务状态
